{'content': '// IKEA Citronhaj Spice Jar Stand
// Jar dimensions: Diameter 40mm, Height 120mm
// Grid: 3x3
// Tiered levels: 30mm step size

jar_diameter = 40;
tolerance = 1.6; // Extra space for easy fit
wall_thickness = 2.4; // 3 perimeters with 0.4 nozzle
cell_size = jar_diameter + tolerance + wall_thickness; 
hole_diameter = jar_diameter + tolerance;

tier_step = 30;
bottom_thickness = 3;
min_socket_depth = 25; // Depth to hold the jar securely

module spice_jar_stand() {
    difference() {
        // Main block - stepped levels
        union() {
            for (row = [0:2]) {
                height = min_socket_depth + bottom_thickness + row * tier_step;
                translate([0, row * cell_size, 0])
                    cube([3 * cell_size, cell_size, height]);
            }
        }

        // Holes for jars
        for (row = [0:2]) {
            for (col = [0:2]) {
                // Hole center
                cx = col * cell_size + cell_size/2;
                cy = row * cell_size + cell_size/2;

                // Total height of the block at this row
                block_height = min_socket_depth + bottom_thickness + row * tier_step;

                // Cut the hole starting from the top, leaving a floor
                translate([cx, cy, bottom_thickness])
                    cylinder(h = block_height, d = hole_diameter, $fn=80);
            }
        }

        // Front aesthetic slant - optional but makes it look less bulky
        // and uses less filament
