{'content': '// IKEA Citronhaj Spice Jar Stand
// 3x3 Grid, Tiered Levels (30mm steps)

jar_diameter = 40;
tolerance = 1.6; // For easy insertion of the 40mm jar
wall_thickness = 3; 
cell_size = jar_diameter + tolerance + wall_thickness;
hole_diameter = jar_diameter + tolerance;

tier_step = 30;
bottom_thickness = 3;
front_socket_height = 30; // Height of the front-most row walls

module spice_jar_stand() {
    difference() {
        // Build the solid stepped base
        union() {
            for (row = [0:2]) {
                row_height = front_socket_height + (row * tier_step);
                translate([0, row * cell_size, 0])
                    cube([3 * cell_size, cell_size, row_height]);
            }
        }

        // Cut out the holes for the jars
        for (row = [0:2]) {
            for (col = [0:2]) {
                cx = col * cell_size + cell_size/2;
                cy = row * cell_size + cell_size/2;

                // Cut starts from bottom_thickness and goes up through the top
                total_height = front_socket_height + (row * tier_step);
                translate([cx, cy, bottom_thickness])
                    cylinder(h = total_height, d = hole_diameter, $fn=100);
            }
        }

        // Circular cutouts on sides for aesthetics and visibility
        for (row = [0:2]) {
            h_center = (front_socket_height + row * tier_step) / 2 + bottom_thickness / 2;

            // Side cutouts (left side)
            translate([-1, row * cell_size + cell_size/2, h_center])
                rotate([0, 90, 0])
                    cylinder(h = wall_thickness + 2, d = (front_socket_height + row * tier_step) * 0.6, $fn=50);

            // Side cutouts (right side)
            translate([3 * cell_size - wall_thickness + 1, row * cell_size + cell_size/2, h_center])
                rotate([0, 90, 0])
                    cylinder(h = wall_thickness + 2, d = (front_socket_height + row * tier_step) * 0.6, $fn=50);
        }
    }
}

spice_jar_stand();

// Preview jars (transparent)
%for (row = [0:2]) {
    for (col = [0:2]) {
        translate([col * cell_size + cell_size/2, row * cell_size + cell_size/2, bottom_thickness])
            cylinder(h = 120, d = 40, $fn=50);
    }
}
'}

